from lib import *
S = SS('g44')
steps = [
    step("一个 goroutine 占多少内存:1 万、10 万、50 万个阻塞在 channel 上的 goroutine。10 万个:StackInuse +195 MiB、HeapInuse +63 MiB、MSpanInuse +2 MiB、Sys +263 MiB、进程最大 RSS +262 MiB,折算每个:栈 2050 字节 + 堆 665 字节(g 结构体等)+ span 元数据 23 字节,Sys 合计 2758 字节;50 万个:Sys +1320 MiB,每个栈 2049 + 堆 652 + span 22,合计 2768 字节,创建加就绪每个 1148 ns。", t=tl(S(1)), done=lidx(S(1), '10000 个 goroutine'), mark=lidx(S(1), '100000 个 goroutine', '500000 个 goroutine', '折算每个 goroutine:栈 2050'), b=bars([['栈(字节)', 2050, '2050'], ['堆(g 结构体等)', 665, '665'], ['span 元数据', 23, '23']], 2050, done=[0], mark=[1, 2]), kv=KV([['栈', '约 2050 字节'], ['堆里的 g 结构体等', '约 650–670 字节'], ['合计(Sys)', '约 2.7–2.8 KB / 个;50 万个 1320 MiB'], ['创建 + 就绪', '798 → 925 → 1148 ns / 个(随数量变大)']], ['合计(Sys)'])),
    step("创建一个 goroutine 要多久:go func(){ wg.Done() }() 创建并跑完,50 万个一轮、5 轮:中位 346 ns/个(331、331、346、355、350);对照:无缓冲 channel 一次发送加接收 131 ns。", t=tl(S(2)), mark=lidx(S(2), 'wg.Done()'), b=bars([['创建并跑完一个 goroutine(ns)', 346, '346'], ['channel 一次收发', 131, '131']], 346, done=[1], mark=[0]), kv=KV([['创建并跑完', '346 ns'], ['channel 一次发送加接收', '131 ns'], ['结论', '一个 goroutine 的创建与退出约等于几次 channel 通信']], ['结论'])),
    step("goroutine 之间切换的成本:两个 goroutine 经无缓冲 channel 来回一次(两次切换):GOMAXPROCS=1 中位 189 ns;GOMAXPROCS=2 为 240 ns;GOMAXPROCS=10 为 254 ns——多个 P 并不让这种强同步的来回变快,反而略慢。", t=tl(S(3)), done=lidx(S(3), 'GOMAXPROCS= 1'), mark=lidx(S(3), 'GOMAXPROCS= 2', 'GOMAXPROCS=10'), b=bars([['GOMAXPROCS=1', 189, '189'], ['GOMAXPROCS=2', 240, '240'], ['GOMAXPROCS=10', 254, '254']], 254, done=[0], mark=[1, 2]), kv=KV([['P=1', '189 ns / 来回一次'], ['P=2', '240 ns'], ['P=10', '254 ns']], ['P=1'])),
    step("对照 OS 线程:每个 goroutine 调用 runtime.LockOSThread 并阻塞,就占住一个线程。1000 个:创建 21 ms(每个 22 µs),进程最大 RSS +56 MiB(每个约 57 KiB);2000 个:131 ms(每个 66 µs),+111 MiB;4000 个:487 ms(每个 122 µs),+221 MiB。本机对单个进程线程数的限制是 4096(kern.num_taskthreads)。线程的创建比 goroutine 慢两个数量级(22–122 µs 对 0.35 µs),并且创建越多越慢。", t=tl(S(4)), done=lidx(S(4), '1000 个 LockOSThread', '2000 个 LockOSThread'), mark=lidx(S(4), '4000 个 LockOSThread', 'kern.num_taskthreads'), b=bars([['goroutine 创建(µs)', 0.346, '0.35'], ['线程创建 1000 个时', 22, '22'], ['线程创建 4000 个时', 122, '122']], 122, done=[0], mark=[1, 2]), kv=KV([['创建一个线程', '22 µs(1000 个)→ 122 µs(4000 个)'], ['每个线程的 RSS', '约 57 KiB(只算已驻留)'], ['本机上限', '4096 个线程 / 进程']], ['创建一个线程'])),
    step("Go 自己的线程数上限:默认 10000;debug.SetMaxThreads(500) 之后让 1000 个 goroutine 各占一个线程:runtime: program exceeds 500-thread limit,fatal error: thread exhaustion,退出码 2。", t=tl(S(5)), mark=lidx(S(5), 'thread exhaustion', '500-thread limit'), kv=KV([['SetMaxThreads', '返回旧值 10000(默认上限)'], ['超过上限', 'fatal error: thread exhaustion'], ['含义', '阻塞在系统调用或 LockOSThread 里的 goroutine 才会占线程']], ['超过上限'])),
]
A = mkartg('g44', 44, 'Go,goroutine,内存,调度,线程,真实验证,动画演示',
    '在 Go 1.27.1(arm64 macOS)里量 goroutine 的成本:一个阻塞的 goroutine 约 2.7–2.8 KB(栈 2050 字节 + 堆里的 g 结构体等约 650 字节),50 万个共 1320 MiB;创建并跑完一个约 346 ns(一次 channel 收发 131 ns);两个 goroutine 经 channel 来回一次 189–254 ns;对照 OS 线程创建 22–122 µs、每个约 57 KiB RSS,本机上限 4096;Go 的 SetMaxThreads 超限会 fatal error: thread exhaustion。',
    '“goroutine 很轻”是 Go 的卖点。轻到什么程度?这篇不说“几 KB”这种概数,而是真的创建几万到 50 万个,量内存、创建时间、切换时间,再拿 OS 线程做对照,最后看线程数的上限怎么表现。',
    [('≈ 2.8 KB', '一个阻塞的 goroutine 的总内存(栈 2050 字节 + 堆约 650 字节)'), ('346 ns', '创建并跑完一个 goroutine(一次 channel 收发是 131 ns)'), ('22–122 µs', '创建一个 OS 线程的耗时,随线程数增加而变长')],
    [('内存', '<p>栈是大头(2 KiB 起步),另有 650 字节左右的 g 结构体及运行时元数据,合计约 2.8 KB。规模对线性:10 万个 262 MiB,50 万个 1.3 GiB。创建加就绪的平均耗时从 0.8 µs 涨到 1.1 µs,说明规模大了之后分配与调度的开销在增加(没有查具体原因)。</p>'),
     ('创建', '<p>创建并跑完一个最小的 goroutine 约 346 ns,约等于三次 channel 通信(131 ns 一次)。所以“每个请求一个 goroutine”在 Go 里是合理的默认,开销是亚微秒级。</p>'),
     ('切换', '<p>两个 goroutine 经无缓冲 channel 来回一次(两次切换)只要 189 ns(P=1)。有意思的是 P 更多时反而更慢(240–254 ns),我猜是强同步的来回要跨 P 唤醒对方,这个解释没有做进一步验证。</p>'),
     ('与线程对比', '<p>让每个 goroutine 占住一个 OS 线程(<code>LockOSThread</code>),创建一个要 22 µs 起,线程多了还会变慢(4000 个时 122 µs),比 goroutine 慢约两个数量级;每个线程光已驻留的内存就约 57 KiB(RSS,不含未触碰的虚拟栈),本机对单进程线程数的上限是 4096。这些数字是 macOS 上的,Linux 上不同。</p>'),
     ('线程上限', '<p>Go 运行时自己也限制线程数(默认 10000),超出时 <code>fatal error: thread exhaustion</code>。普通的 goroutine 不占线程,只有阻塞在系统调用、cgo 或 <code>LockOSThread</code> 里的才会占——所以几十万个 goroutine 没问题,几千个阻塞在 cgo 里的就可能出问题(见 cgo 一篇)。</p>')],
    steps,
    [ENV_G + '。内存数字来自 runtime.MemStats 的 StackInuse / HeapInuse / MSpanInuse / Sys 在创建前后的差与 getrusage 的最大 RSS;所有 goroutine 阻塞在 channel 上,创建时间含等待它们都就绪;线程实验用 runtime.LockOSThread;每个设置只跑一次(创建时间 5 轮)',
     '没有验证:Linux 上的数字(线程栈大小、内核限制不同)、自适应初始栈大小对 goroutine 内存的影响、更大规模(百万级以上)时的行为、GC 扫描大量 goroutine 栈的成本(见 GC 停顿一篇的现象)、goroutine 切换在多 P 下变慢的原因'],
    'goroutine 的成本')
